import { describe, expect, it } from "vitest";
import headers from "../public/_headers?raw";
import { PAPER, pwaOptions } from "../pwa.config";
import { PAPER as CANVAS_PAPER } from "./surface";

const publicIcons = Object.keys(import.meta.glob("../public/icons/*.png")).map((path) =>
  path.replace("../public", ""),
);

describe("pwa config", () => {
  const manifest = pwaOptions.manifest || {};

  it("declares an installable standalone app that opens the default board", () => {
    expect(manifest).toMatchObject({
      name: "Stallion",
      short_name: "Stallion",
      display: "standalone",
      orientation: "any",
      start_url: "/b/default",
    });
  });

  it("paints the splash and title bar in the canvas paper colour", () => {
    expect(PAPER).toBe(CANVAS_PAPER);
    expect(manifest.theme_color).toBe(CANVAS_PAPER);
    expect(manifest.background_color).toBe(CANVAS_PAPER);
  });

  it("ships 192, 512 and maskable 512 icons that exist in public", () => {
    const icons = manifest.icons ?? [];
    expect(icons.map((icon) => `${icon.sizes} ${icon.purpose}`)).toEqual([
      "192x192 any",
      "512x512 any",
      "512x512 maskable",
    ]);
    for (const icon of icons) expect(publicIcons).toContain(icon.src);
  });

  it("updates itself and never serves api routes or the socket from the worker", () => {
    expect(pwaOptions.registerType).toBe("autoUpdate");
    expect(pwaOptions.workbox).toMatchObject({ clientsClaim: true, skipWaiting: true });
    expect(pwaOptions.workbox?.runtimeCaching).toEqual([]);
    const allow = pwaOptions.workbox?.navigateFallbackAllowlist ?? [];
    const deny = pwaOptions.workbox?.navigateFallbackDenylist ?? [];
    const fallsBack = (path: string) =>
      allow.some((pattern) => pattern.test(path)) && !deny.some((pattern) => pattern.test(path));
    expect(fallsBack("/b/default")).toBe(true);
    expect(fallsBack("/api/boards/default/ws")).toBe(false);
    expect(fallsBack("/sw.js")).toBe(false);
  });

  it("tells Cloudflare not to cache the worker script or the manifest", () => {
    expect(headers).toMatch(/^\/sw\.js\n {2}Cache-Control: no-cache$/m);
    expect(headers).toMatch(/^\/manifest\.webmanifest\n {2}Cache-Control: no-cache$/m);
  });
});
=== boot.ts ===
import { errorMessage, reportLink } from "./report";

export type AppModule<Root> = { mount(root: Root): void };

export const bootFailureMessage = (error: unknown): string =>
  `The drawing board could not start: ${errorMessage(error)}`;

export const boot = <Root>(
  root: Root,
  load: () => Promise<AppModule<Root>>,
  onFailure: (message: string) => void,
): Promise<void> =>
  load()
    .then((app) => app.mount(root))
    .catch((error: unknown) => onFailure(bootFailureMessage(error)));

export const showBootFailure = (root: HTMLElement, message: string): void => {
  const panel = document.createElement("div");
  panel.setAttribute("role", "alert");
  panel.style.cssText =
    "margin:16px;padding:12px 16px;border:1px solid #e5484d;border-radius:10px;background:#fff5f5;color:#8a1c1f;font-family:system-ui,sans-serif";
  const text = document.createElement("p");
  text.style.margin = "0 0 8px";
  text.textContent = `${message}. Reload to try again.`;
  const link = document.createElement("a");
  link.href = reportLink(message);
  link.target = "_blank";
  link.rel = "noreferrer";
  link.textContent = "Report an issue";
  panel.append(text, link);
  root.replaceChildren(panel);
};
=== boot.test.ts ===
import { describe, expect, it } from "vitest";
import { boot } from "./boot";

const root = { id: "app" };

describe("boot", () => {
  it("reports a module that fails to load instead of leaving a blank page", async () => {
    const failures: string[] = [];
    await boot(
      root,
      () => Promise.reject(new TypeError("Failed to fetch dynamically imported module")),
      (message) => failures.push(message),
    );
    expect(failures).toEqual([
      "The drawing board could not start: Failed to fetch dynamically imported module",
    ]);
  });

  it("reports a mount that throws", async () => {
    const failures: string[] = [];
    await boot(
      root,
      async () => ({
        mount: () => {
          throw new Error("crypto.randomUUID is not a function");
        },
      }),
      (message) => failures.push(message),
    );
    expect(failures).toEqual([
      "The drawing board could not start: crypto.randomUUID is not a function",
    ]);
  });

  it("mounts once the app loads", async () => {
    const mounted: (typeof root)[] = [];
    await boot(
      root,
      async () => ({ mount: (target) => mounted.push(target) }),
      () => undefined,
    );
    expect(mounted).toEqual([root]);
  });
});

