                <span class="recent-time">{relativeTime(recent.lastOpened, Date.now())}</span>
              </button>
              <input
                class="recent-name"
                value={recent.name}
                aria-label={`Name for board ${recent.id}`}
                onInput={(event) => editName(recent.id, event.currentTarget.value)}
                onBlur={commitNames}
                onKeyDown={(event) => {
                  if (event.key === "Enter") event.currentTarget.blur();
                }}
              />
              <button
                type="button"
                class="recent-remove"
                aria-label={`Forget board ${recent.name}`}
                title="Remove from this device's recent boards"
                onClick={() => remove(recent.id)}
              >
                <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true">
                  <path
                    d="M6 6l12 12M18 6L6 18"
                    fill="none"
                    stroke="currentColor"
                    stroke-width="2"
                    stroke-linecap="round"
                  />
                </svg>
              </button>
            </li>
          ))}
        </ul>
      )}
    </main>
  );
}

