.swatch {
  position: relative;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 2px var(--panel);
}

.swatch[aria-pressed="true"] {
  border-color: transparent;
  box-shadow:
    inset 0 0 0 2px var(--panel),
    0 0 0 2px var(--panel),
    0 0 0 5px var(--ink);
}

.swatch.secondary::after {
  content: "";
  position: absolute;
  right: -5px;
  bottom: -5px;
  width: 10px;
  height: 10px;
  border: 2px solid var(--panel);
  border-radius: 50%;
  background: var(--ink);
}

.pair {
